from decimal import Decimal
from ledgerly.importers import parse_amount
from ledgerly.errors import BillingError

valid = {
    "$1,234.50": Decimal("1234.50"),
    " 12 ": Decimal("12.00"),
    "0": Decimal("0.00"),
    "0.00": Decimal("0.00"),
    "$0.5": Decimal("0.50"),
    "1,000,000.99": Decimal("1000000.99"),
    "   $ 7.25  ": None,  # space after $ -> invalid
}
